-- Issue #61: a daily BOM's approval becomes a review — pending, approved or
-- rejected — with a reviewer and a management note.
--
-- Generated by `prisma migrate dev --create-only`, then amended where it was
-- created: Prisma reads the `approved_by` -> `reviewed_by` rename as a drop
-- and an add, which would lose every recorded approver, so it is a RENAME
-- here instead. The stored status 'unapproved' becomes 'pending'; 'approved'
-- keeps its value. Every existing row starts with no management note and no
-- pending review changes.

-- AlterTable
ALTER TABLE "bom" RENAME COLUMN "approved_by" TO "reviewed_by";

ALTER TABLE "bom" ADD COLUMN     "management_note" TEXT,
ADD COLUMN     "pending_review_changes" JSONB NOT NULL DEFAULT '[]',
ALTER COLUMN "approval_status" SET DEFAULT 'pending';

-- Data
UPDATE "bom" SET "approval_status" = 'pending' WHERE "approval_status" = 'unapproved';
